package com.healthcare.portal.service; import com.healthcare.portal.entity.*; import com.healthcare.portal.repository.AuditLogRepository; import org.springframework.stereotype.Service; @Service public class AuditService { private final AuditLogRepository repo; public AuditService(AuditLogRepository r){repo=r;} public void log(User actor,String action,String type,Long id,String details){repo.save(new AuditLog(actor,action,type,id,details));} }
